1	/**
2	 * What MHPCO knows about the customer's standing: the facts of their history
3	 * with the office that its policy-wide discount rules are written against.
4	 */
5	export interface Customer {
6	  yearsWithMHPCO: number;
7	  /** Contracts this customer already holds, before the one being quoted. */
8	  previousContracts?: number;
9	}
10	
11	export interface Item {
12	  type: string;
13	  cursed?: boolean;
14	  enchantment?: number;
15	}
16	
17	const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
18	  sword: 100,
19	  amulet: 60,
20	  staff: 80,
21	  potion: 40,
22	};
23	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
24	const COMPONENT_BASE_PREMIUM = 25;
25	const BLOCK_SIZE = 3;
26	const BLOCK_BASE_PREMIUM = 60;
27	const CURSE_SURCHARGE_RATE = 0.5;
28	const HIGH_ENCHANTMENT_LEVEL = 5;
29	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
30	const LOYALTY_YEARS = 2;
31	const LOYALTY_DISCOUNT_RATE = 0.2;
32	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
33	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
34	const PROCESSING_FEE = 5;
35	
36	function isComponent(item: Item): boolean {
37	  return COMPONENT_TYPES.has(item.type);
38	}
39	
40	function isMainItem(item: Item): boolean {
41	  return !isComponent(item);
42	}
43	
44	function mainItemBasePremium(item: Item): number {
45	  return MAIN_ITEM_BASE_PREMIUMS[item.type];
46	}
47	
48	function alikeGroupBasePremium(count: number): number {
49	  return count === BLOCK_SIZE
50	    ? BLOCK_BASE_PREMIUM
51	    : count * COMPONENT_BASE_PREMIUM;
52	}
53	
54	/** Components are "alike" when they are of exactly the same type. */
55	function alikeKey(component: Item): string {
56	  return component.type;
57	}
58	
59	function componentsBasePremium(components: Item[]): number {
60	  const countsPerAlikeGroup = new Map<string, number>();
61	  for (const component of components) {
62	    const key = alikeKey(component);
63	    countsPerAlikeGroup.set(key, (countsPerAlikeGroup.get(key) ?? 0) + 1);
64	  }
65	  return [...countsPerAlikeGroup.values()].reduce(
66	    (total, count) => total + alikeGroupBasePremium(count),
67	    0,
68	  );
69	}
70	
71	function curseSurcharge(item: Item): number {
72	  return item.cursed === true
73	    ? mainItemBasePremium(item) * CURSE_SURCHARGE_RATE
74	    : 0;
75	}
76	
77	function isHighlyEnchanted(item: Item): boolean {
78	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
79	}
80	
81	function highEnchantmentSurcharge(item: Item): number {
82	  return isHighlyEnchanted(item)
83	    ? mainItemBasePremium(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
84	    : 0;
85	}
86	
87	/**
88	 * Item-specific modifiers apply to the base premium of the affected item and
89	 * are added to it, never multiplied onto it. Each risk rule is independent:
90	 * its own condition, its own rate.
91	 */
92	function itemSpecificModifiers(item: Item): number {
93	  return curseSurcharge(item) + highEnchantmentSurcharge(item);
94	}
95	
96	function mainItemsBasePremium(mainItems: Item[]): number {
97	  return mainItems.reduce((total, item) => total + mainItemBasePremium(item), 0);
98	}
99	
100	/** The policy base premium: the sum of all unmodified item base premiums. */
101	function policyBasePremiumFor(items: Item[]): number {
102	  return (
103	    mainItemsBasePremium(items.filter(isMainItem)) +
104	    componentsBasePremium(items.filter(isComponent))
105	  );
106	}
107	
108	/** The item-specific surcharges of every affected item, summed. */
109	function itemSpecificModifiersFor(items: Item[]): number {
110	  return items
111	    .filter(isMainItem)
112	    .reduce((total, item) => total + itemSpecificModifiers(item), 0);
113	}
114	
115	/**
116	 * Rounding in the MHPCO's favour is a single policy with two arms: an amount
117	 * the customer pays goes up, an amount MHPCO pays out goes down. This is the
118	 * premium arm; it is named for the amount it rounds so that a payout can never
119	 * reach it by mistake.
120	 */
121	function roundPremiumInMHPCOsFavour(premium: number): number {
122	  return Math.ceil(premium);
123	}
124	
125	/** Every item in a quote is treated as a first insurance. */
126	function firstInsuranceSurcharge(policyBasePremium: number): number {
127	  return policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
128	}
129	
130	function isLongStanding(customer: Customer): boolean {
131	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
132	}
133	
134	function loyaltyDiscount(customer: Customer, policyBasePremium: number): number {
135	  return isLongStanding(customer)
136	    ? policyBasePremium * LOYALTY_DISCOUNT_RATE
137	    : 0;
138	}
139	
140	function isFollowUpContract(customer: Customer): boolean {
141	  return (customer.previousContracts ?? 0) > 0;
142	}
143	
144	function followUpDiscount(
145	  customer: Customer,
146	  policyBasePremium: number,
147	): number {
148	  return isFollowUpContract(customer)
149	    ? policyBasePremium * FOLLOW_UP_DISCOUNT_RATE
150	    : 0;
151	}
152	
153	/**
154	 * Policy-wide modifiers apply to the policy base premium (the sum of all item
155	 * base premiums) and are added to it, never multiplied onto it. Each rule is
156	 * independent: its own condition, its own rate. Surcharges raise the premium
157	 * and discounts lower it; each is computed as a positive amount off the
158	 * unmodified policy base premium and given its sign here.
159	 */
160	function policyWideModifiers(
161	  customer: Customer,
162	  policyBasePremium: number,
163	): number {
164	  return (
165	    firstInsuranceSurcharge(policyBasePremium) -
166	    loyaltyDiscount(customer, policyBasePremium) -
167	    followUpDiscount(customer, policyBasePremium)
168	  );
169	}
170	
171	export function quote(customer: Customer, items: Item[]): number {
172	  const policyBasePremium = policyBasePremiumFor(items);
173	  const premium =
174	    policyBasePremium +
175	    itemSpecificModifiersFor(items) +
176	    policyWideModifiers(customer, policyBasePremium) +
177	    PROCESSING_FEE;
178	  return roundPremiumInMHPCOsFavour(premium);
179	}
