43	    const runes = Array.from({ length: 7 }, () => ({ type: "rune" }));
44	    expect(quote({ yearsWithMHPCO: 0 }, runes)).toBe(198);
45	  });
46	  it("quotes 2 runes + 1 moonstone -- base premium 75 G (no block: different types) (75 + 7.5 + 5 = 87.5 -> 88 G)", () => {
47	    const items = [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }];
48	    expect(quote({ yearsWithMHPCO: 0 }, items)).toBe(88);
49	  });
50	  it("quotes 3 runes + 3 moonstones -- base premium 120 G (two separate blocks) (120 + 12 + 5 = 137 G)", () => {
51	    const items = [
52	      ...Array.from({ length: 3 }, () => ({ type: "rune" })),
53	      ...Array.from({ length: 3 }, () => ({ type: "moonstone" })),
54	    ];
55	    expect(quote({ yearsWithMHPCO: 0 }, items)).toBe(137);
56	  });
57	
58	  // --- Quote: item-specific modifiers ---
59	  it("adds a 50 % curse surcharge to the cursed item's base premium -- cursed sword 100 G -> 150 G (100 base + 50 curse + 10 first insurance + 5 fee = 165 G)", () => {
60	    const items = [{ type: "sword", cursed: true }];
61	    expect(quote({ yearsWithMHPCO: 0 }, items)).toBe(165);
62	  });
63	  it("adds a 30 % high-enchantment surcharge at enchantment exactly 5 -- sword 100 G -> 130 G (100 + 30 + 10 + 5 = 145 G)", () => {
64	    const items = [{ type: "sword", enchantment: 5 }];
65	    expect(quote({ yearsWithMHPCO: 0 }, items)).toBe(145);
66	  });
67	  it("adds no high-enchantment surcharge at enchantment 4 -- sword stays 100 G (100 + 10 + 5 = 115 G)", () => {
68	    const items = [{ type: "sword", enchantment: 4 }];
69	    expect(quote({ yearsWithMHPCO: 0 }, items)).toBe(115);
70	  });
71	  it("applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5 -- 100 G -> 180 G (100 + 50 + 30 + 10 + 5 = 195 G)", () => {
72	    const items = [{ type: "sword", enchantment: 5, cursed: true }];
73	    expect(quote({ yearsWithMHPCO: 0 }, items)).toBe(195);
74	  });
75	
76	  // --- Quote: modifier scope on multi-item policies ---
77	  it("applies the curse surcharge only to the cursed item -- cursed sword + plain amulet -> 160 G base + 50 G = 210 G before further modifiers and fee (+16 first insurance + 5 fee = 231 G)", () => {
78	    const items = [
