90	  it("applies the 20 % loyalty discount at exactly 2 years with MHPCO -- sword: 100 + 10 - 20 + 5 = 95 G", () => {
91	    expect(quote({ yearsWithMHPCO: 2 }, [{ type: "sword" }])).toBe(95);
92	  });
93	  it("applies no loyalty discount at 1 year with MHPCO -- sword: 100 + 10 + 5 = 115 G", () => {
94	    expect(quote({ yearsWithMHPCO: 1 }, [{ type: "sword" }])).toBe(115);
