112	  it("keeps intermediate amounts as fractions and rounds only the final premium -- 3-year customer, 1 rune: 25 + 2.5 - 5 = 22.5, + 5 fee = 27.5 -> 28 G", () => {
113	    expect(quote({ yearsWithMHPCO: 3 }, [{ type: "rune" }])).toBe(28);
