115	
116	  // --- Quote: integration examples ---
117	  it("quotes a newcomer's cursed steel sword (enchantment 3, 0 years) -- premium 165 G", () => {
118	    const customer = { yearsWithMHPCO: 0, previousContracts: 0 };
119	    const items = [
120	      { type: "sword", material: "steel", enchantment: 3, cursed: true },
121	    ];
122	    expect(quote(customer, items)).toBe(165);
123	  });
124	  it.todo("quotes a long-standing customer's second contract: cursed sword enchantment 7, 3 years -- premium 160 G");
125	
126	  // --- Quote: rejection ---
