128	
129	  // --- Claim: insurance sum and cap ---
130	  it.todo("caps a single-sword policy at 2000 G (twice the 1000 G insurance sum)");
131	  it.todo("sums insurance values across items -- sword + amulet -> insurance sum 1600 G, cap 3200 G");
132	  it.todo("bases the cap on unmodified insurance values -- cursed sword (premium 165 G) -> cap 2000 G");
133	  it.todo("counts component insurance values at 250 G each -- sword + 3 runes -> insurance sum 1750 G (block affects premium only)");
134	  it.todo("counts two swords as insurance sum 2000 G, cap 4000 G");
135	
