139	  it.todo("applies the 100 G deductible once per damaged item -- sword 500 G + amulet 300 G -> payout 600 G");
140	  it.todo("treats each damages entry of the same item type as a separate damage with its own deductible -- two damaged swords");
141	
142	  // --- Claim: special clauses ---
143	  it.todo("reimburses damage to an item with enchantment exactly 8 at 50 % -- dragon sword, damage 1000 G -> payout 400 G");
144	  it.todo("reimburses dragon-material damage fully -- dragon sword enchantment 5, damage 800 G -> payout 700 G");
145	  it.todo("lets the 50 % high-enchantment rule win over full dragon reimbursement -- dragon sword enchantment 9, damage 1000 G -> payout 400 G");
146	  it.todo("applies the high-enchantment clause alone to a steel sword enchantment 9, damage 1000 G -> payout 400 G");
147	
